-- Migration: 012_task_manager_data.sql
-- Copies the Task Manager data out of its own Supabase project into the Bangla
-- Tools database. Generated from a pg_dump --column-inserts export, with two
-- deliberate transformations:
--
--   1. Tables rewritten to their tm_ prefixed names (see 011).
--
--   2. user_id / created_by rewritten to the static sentinel owner
--      00000000-0000-0000-0000-000000000111. In the source project this data
--      was split across two auth.users accounts; Bangla Tools has a single
--      static identity (VITE_TM_USER_ID) and no Supabase Auth, so ownership
--      collapses onto that one id. Without this the rows would be invisible in
--      the app, whose queries filter on the configured user id.
--
--      Only those two specific auth user ids are substituted -- primary keys
--      and tag references keep their original values, so every relationship in
--      the data survives the copy intact.
--
-- Run AFTER 011. Safe to re-run: every insert is ON CONFLICT DO NOTHING.
--
-- Wrapped in one transaction with constraints deferred, because
-- tm_to_do_task.parent_task references tm_to_do_task and a child row can
-- appear in this file before its parent.

BEGIN;
SET CONSTRAINTS ALL DEFERRED;

-- 0 row(s) into tm_task_type

-- 10 row(s) into tm_task_tag

-- 0 row(s) into tm_task_tag_task_type

-- 1053 row(s) into tm_task

-- 10 row(s) into tm_to_do_task

-- 3 row(s) into tm_vocabulary

-- 0 row(s) into tm_vocabulary_map

-- Advance the sequences past the copied ids, or the app's next insert collides
-- with an existing primary key.
SELECT setval('tm_vocabulary_id_seq',     COALESCE((SELECT max(id) FROM tm_vocabulary), 1),     (SELECT count(*) FROM tm_vocabulary) > 0);
SELECT setval('tm_vocabulary_map_id_seq', COALESCE((SELECT max(id) FROM tm_vocabulary_map), 1), (SELECT count(*) FROM tm_vocabulary_map) > 0);

COMMIT;

NOTIFY pgrst, 'reload schema';
